#[derive(Copy, Clone)]

pub fn rgb(
    args: &mut Args,
    /// The red component.
    #[external]
    red: Component,
    /// The green component.
    #[external]
    green: Component,
    /// The blue component.
    #[external]
    blue: Component,
    /// The alpha component.
    #[external]
    alpha: Component,
    /// Alternatively: The color in hexadecimal notation.
    ///
    /// Accepts three, four, six or eight hexadecimal digits and optionally
    /// a leading hash.
    ///
    /// If this is given, the individual components should not be given.
    ///
    /// ```example
    /// #text(16pt, rgb("#239dad"))[
    ///   *Typst*
    /// ]
    /// ```
    #[external]
    hex: Str,
    /// Alternatively: The color to convert to RGB(a).
    ///
    /// If this is given, the individual components should not be given.
    #[external]
    color: Color,
) -> SourceResult<Color> {
    Ok(if let Some(string) = args.find::<Spanned<Str>>()? {
        Self::from_str(&string.v).at(string.span)?
    } else if let Some(color) = args.find::<Color>()? {
        Self::Process(ProcessColor::Rgb(color.to_rgb()))
    } else {
        let Component(r) = args.expect("red component")?;
        let Component(g) = args.expect("green component")?;
        let Component(b) = args.expect("blue component")?;
        let Component(a) = args.eat()?.unwrap_or(Component(Ratio::one()));
        Self::Process(ProcessColor::Rgb(Rgb::new(
            r.get() as f32,
            g.get() as f32,
            b.get() as f32,
            a.get() as f32,
        )))
    })
}

/// Create a CMYK color.
///
/// This is useful if you want to target a specific printer. The conversion
/// to RGB for display preview might differ from how your printer reproduces
/// the color.
///
/// A CMYK color is represented internally by an array of four components:
/// - cyan (@ratio)
/// - magenta (@ratio)
/// - yellow (@ratio)
/// - key (@ratio)
///
/// These components are also available using the
/// @color.components[`components`] method.
///
/// Note that CMYK colors are not currently supported when PDF/A output is
/// enabled.
///
/// ```example
/// #square(
///   fill: cmyk(27%, 0%, 3%, 5%)
/// )
/// ```
#[func(title = "CMYK", since = "forever")]
pub fn cmyk(
    args: &mut Args,
    /// The cyan component.
    #[external]
    cyan: RatioComponent,
    /// The magenta component.
    #[external]
    magenta: RatioComponent,
    /// The yellow component.
    #[external]
    yellow: RatioComponent,
    /// The key component.
    #[external]
    key: RatioComponent,
    /// Alternatively: The color to convert to CMYK.
    ///
    /// If this is given, the individual components should not be given.
    #[external]
    color: Color,
) -> SourceResult<Color> {
    Ok(Self::Process(ProcessColor::Cmyk(
        if let Some(color) = args.find::<Color>()? {
            color.to_cmyk()
        } else {
            let RatioComponent(c) = args.expect("cyan component")?;
            let RatioComponent(m) = args.expect("magenta component")?;
            let RatioComponent(y) = args.expect("yellow component")?;
            let RatioComponent(k) = args.expect("key/black component")?;
            Cmyk::new(c.get() as f32, m.get() as f32, y.get() as f32, k.get() as f32)
        },
    )))
}

